() => {
  const c = document.querySelector('.card').getBoundingClientRect();
  const out = [];
  document.querySelectorAll('.card *').forEach(el=>{
    const r = el.getBoundingClientRect();
    if(r.width===0&&r.height===0) return;
    if(r.left < c.left-0.5 || r.right > c.right+0.5 || r.top < c.top-0.5 || r.bottom > c.bottom+0.5)
      out.push(el.className+' '+JSON.stringify({l:r.left,t:r.top,r:r.right,b:r.bottom}));
  });
  const t = document.querySelector('.title');
  return {card:[c.width,c.height], overflow:out, fontLoaded: document.fonts.check('700 40px Inter'),
    titleBox:[t.getBoundingClientRect().height], docScroll:[document.documentElement.scrollWidth, document.documentElement.scrollHeight]};
}

