async () => {
  const names=['square.png','landscape.png','story.png'];
  const out={};
  for(const n of names){
    const img=new Image();
    img.src='/'+n+'?v='+Date.now();
    await img.decode();
    out[n]=[img.naturalWidth,img.naturalHeight];
  }
  return out;
}

